from pathlib import Path
import json
p=Path('assets/characters/warlock-ignivar/animations/flight-r1')
d=json.loads((p/'animation.json').read_text())
html='''<!doctype html><meta charset="utf-8"><title>Ignivar flight review</title><style>body{margin:20px;background:#171820;color:white;font:16px system-ui}button,select{font:inherit;padding:8px}canvas{width:min(65vw,900px);height:auto;background:#252733}.small{width:122px;background:#eee6d7} .row{display:flex;align-items:center;gap:30px}</style><h1>Ignivar flying revision — pending approval</h1><select id="state"></select><button id="play">Pause</button><button id="restart">Restart</button><button id="bg">Light / dark</button><p id="info"></p><div class="row"><canvas width="1536" height="1536" id="large"></canvas><div>~96px visible height<br><canvas class="small" width="1536" height="1536" id="small"></canvas></div></div><script>const data=DATA; const select=document.querySelector('#state'); for(const name of Object.keys(data.animations))select.add(new Option(name,name));const images=data.frames.map(f=>{const i=new Image();i.src=f.file;return i});let start=performance.now(),playing=true,paused=0,current=-1;select.onchange=()=>{start=performance.now();paused=0;current=-1}; document.querySelector('#restart').onclick=select.onchange;document.querySelector('#play').onclick=()=>{if(playing)paused=performance.now()-start;else start=performance.now()-paused;playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};let light=false;document.querySelector('#bg').onclick=()=>{light=!light;document.querySelector('#large').style.background=light?'#eee6d7':'#252733'};function draw(t){const c=data.animations[select.value],duration=c.durations_ms.reduce((a,b)=>a+b,0);let time=playing?t-start:paused;if(c.loop)time%=duration;else time=Math.min(time,duration-1);let j=0;while(j<c.frames.length-1&&time>=c.durations_ms[j])time-=c.durations_ms[j++];const idx=c.frames[j];if(idx!==current&&images[idx].complete){for(const id of ['large','small']){const ctx=document.querySelector('#'+id).getContext('2d');ctx.clearRect(0,0,1536,1536);ctx.drawImage(images[idx],0,0)}current=idx;document.querySelector('#info').textContent=select.value+' | frame '+idx+' | '+duration+'ms | '+(c.loop?'loop':'one-shot → '+c.transition)}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script>'''.replace('DATA',json.dumps(d))
(p/'preview.html').write_text(html,encoding='utf-8')
(p/'generation-prompts.json').write_text(json.dumps({'tool':'built-in image_gen','reference_identity':d['base'],'motion_reference':'assets/characters/warlock-summons/animations/flight-r1/warlock-imp/source-sheet.png','prompt_summary':'Individual native-resolution transparent whole-character frame generation. Exact approved Ignivar asymmetrical horns, spiked collar, diamond chest, long lean limbs, red/black hard-edged cel rendering. Flying poses with bent knees and tucked talons; up/mid/down wing phases, cast anticipation/release, recoil, wounded wing phases, fall and collapse. No procedural painting or image deformation.','rejected_outputs':['6-pose small sheet','horizontal mid wings with opaque haze, two attempts','landscape terminal with opaque haze'],'accepted_sources':[{k:v for k,v in f.items() if k in ['source','source_sha256','source_dimensions']} for f in d['frames'] if 'source' in f]},indent=2))

